SELECT 
  COUNT(DISTINCT oi.order_id) AS count
FROM 
  commerce.order_items oi
JOIN 
  commerce.order_items oi2 ON oi.order_id = oi2.order_id
JOIN 
  commerce.products p ON oi.product_id = p.product_id
JOIN 
