  EXTRACT(MONTH FROM return_date) AS month,
  COUNT(DISTINCT return_id) AS count
FROM commerce.returns
WHERE return_date >= '2026-01-01' AND return_date < '2027-01-01'
GROUP BY year, month
ORDER BY year, month;
