```sql
SELECT 
  date_trunc('month', s.date) AS month,
  SUM(i.revenue) AS revenue
FROM 
  commerce.sales s
JOIN 
  commerce.invoice_items i ON s.cogs = i.amount
WHERE 
  s.date BETWEEN '2035-01-01' AND '2035-12-31'
GROUP BY 
  month
ORDER BY 
  month;
```

